
clc;
clear;
close all;

%%\ PARAMETROS GENERALES

N = 1000000;

%%\ 3.1.a - MODULACION CON ERROR DE FASE

M = 4;
theta_err = pi/2;

% Generacion de simbolos
[bits, simbolos, simbolos_complejos] = generador_simbolos(N, M);

% Modulacion ideal con Gray
simbolos_ideales = qammod(simbolos, M, 'gray');

% Modulacion con error de fase
simbolos_rotados = miQamMod(simbolos, M, theta_err);


%%\ GRAFICO DE CONSTELACIONES

figure(1); %[output:0c037aee]

subplot(1,2,1); %[output:0c037aee]
scatter(real(simbolos_ideales), imag(simbolos_ideales), 5, 'filled'); %[output:0c037aee]
title('QPSK ideal'); %[output:0c037aee]
xlabel('Parte real (I)'); %[output:0c037aee]
ylabel('Parte imaginaria (Q)'); %[output:0c037aee]
grid on; %[output:0c037aee]
axis equal; %[output:0c037aee]

subplot(1,2,2); %[output:0c037aee]
scatter(real(simbolos_rotados), imag(simbolos_rotados), 5, 'filled'); %[output:0c037aee]
title('QPSK con rotacion de fase'); %[output:0c037aee]
xlabel('Parte real (I)'); %[output:0c037aee]
ylabel('Parte imaginaria (Q)'); %[output:0c037aee]
grid on; %[output:0c037aee]
axis equal; %[output:0c037aee]
%[text] 3.b

%%\ BER En funcion de la  SNR

M = 4;
theta_err = pi/2;

valores_SNR = 1:30;

% GENERACION DE BITS Y SIMBOLOS
[bits, simbolos, ~] = generador_simbolos(N, M);

% CALCULO DE BER
BER_rotacion = calculo_BER_rotacion(bits, simbolos, M, theta_err, valores_SNR);


%%\ GRAFICO DE BER

figure(2); %[output:8190108c]

semilogy(valores_SNR, BER_rotacion, '-o', 'LineWidth', 1.5); %[output:8190108c]

grid on; %[output:8190108c]
xlabel('SNR (dB)'); %[output:8190108c]
ylabel('BER'); %[output:8190108c]
title('BER en funcion de la SNR - Error de rotacion'); %[output:8190108c]

legend('QPSK con error de fase'); %[output:8190108c]
xlim([1 30]); %[output:8190108c]
%[text] 3.c BER EN FUNCION DEL ERROR DE FASE
M = 4;
SNR_dB = 5;

% VALORES DEL ERROR DE FASE
valores_fase = 0:pi/36:pi/2;

% GENERACION DE BITS Y SIMBOLOS
[bits, simbolos, ~] = generador_simbolos(N, M);

% CALCULO DE BER
BER_fase = calculo_BER_fase(bits, simbolos, M, valores_fase, SNR_dB);


%%\ GRAFICO DE BER

figure(3); %[output:9623d043]

plot(valores_fase, BER_fase, '-o', 'LineWidth', 1.5); %[output:9623d043]

grid on; %[output:9623d043]
xlabel('Error de fase (rad)'); %[output:9623d043]
ylabel('BER'); %[output:9623d043]
title('BER en funcion del error de fase - QPSK'); %[output:9623d043]

xticks(0:pi/12:pi/2); %[output:9623d043]
xticklabels({'0', '\pi/12', '\pi/6', '\pi/4', '\pi/3', '5\pi/12', '\pi/2'}); %[output:9623d043]

xlim([0 pi/2]); %[output:9623d043]
%[text] 3.d BER EN FUNCION DEL ORDEN DE MODULACION
valores_M = [2 4 16];

theta_err = pi/4;
SNR_dB = 5;

BER_orden = zeros(size(valores_M));

for i = 1:length(valores_M)

    M = valores_M(i);

    k = log2(M);
    bits = randi([0 1], N*k, 1);

    bits_agrupados = reshape(bits, k, []).';
    simbolos = bi2de(bits_agrupados, 'left-msb');

    BER_orden(i) = calculo_BER_fase(bits, simbolos, M, theta_err, SNR_dB);

end

%%\ GRAFICO DE BER

figure(4); %[output:6d837c3a]

semilogy(valores_M, BER_orden, '-o', 'LineWidth', 1.5); %[output:6d837c3a]

grid on; %[output:6d837c3a]
xlabel('Orden de modulacion (M)'); %[output:6d837c3a]
ylabel('BER'); %[output:6d837c3a]
title('BER en funcion del orden de modulacion'); %[output:6d837c3a]

xticks(valores_M); %[output:6d837c3a]
%[text] 
%[text] 3.2.b - BER EN FUNCION DE LA SNR
M = 4;
phi_err = pi/6;

valores_SNR = 1:30;

[bits, simbolos, ~] = generador_simbolos(N, M);

BER_cuadratura = calculo_BER_cuadratura(bits, simbolos, M, phi_err, valores_SNR);

BER_ideal = calculo_BER_cuadratura(bits, simbolos, M, 0, valores_SNR);

figure(5); %[output:156c972f]
semilogy(valores_SNR, BER_cuadratura, '-o', 'LineWidth', 1.5); %[output:156c972f]
hold on; %[output:156c972f]
semilogy(valores_SNR, BER_ideal, '-s', 'LineWidth', 1.5); %[output:156c972f]
hold off; %[output:156c972f]

grid on; %[output:156c972f]
xlabel('SNR (dB)'); %[output:156c972f]
ylabel('BER'); %[output:156c972f]
title('BER en funcion de la SNR - Error de cuadratura'); %[output:156c972f]
legend('QPSK con error de cuadratura', 'QPSK ideal'); %[output:156c972f]
xlim([1 30]); %[output:156c972f]

%[text] 3.2.c - BER EN FUNCION DEL ERROR DE FASE
M = 4;
SNR_dB = 5;

valores_fase = 0:pi/36:pi/2;

[bits, simbolos, ~] = generador_simbolos(N, M);

BER_fase_cuadratura = calculo_BER_fase_cuadratura(bits, simbolos, M, valores_fase, SNR_dB);

figure(6); %[output:8cea1296]
plot(valores_fase, BER_fase_cuadratura, '-o', 'LineWidth', 1.5); %[output:8cea1296]

grid on; %[output:8cea1296]
xlabel('Error de fase (rad)'); %[output:8cea1296]
ylabel('BER'); %[output:8cea1296]
title('BER en funcion del error de cuadratura - QPSK'); %[output:8cea1296]
xticks(0:pi/12:pi/2); %[output:8cea1296]
xticklabels({'0', '\pi/12', '\pi/6', '\pi/4', '\pi/3', '5\pi/12', '\pi/2'}); %[output:8cea1296]
xlim([0 pi/2]); %[output:8cea1296]
%[text] 
%[text] 3.2.d - BER EN FUNCION DEL ORDEN DE MODULACION
valores_M = [4 16 64];

phi_err = pi/12;
SNR_dB = 15;

BER_orden_cuadratura = zeros(size(valores_M));

for i = 1:length(valores_M)

    M = valores_M(i);
    k = log2(M);

    bits = randi([0 1], N*k, 1);

    bits_agrupados = reshape(bits, k, []).';
    simbolos = bi2de(bits_agrupados, 'left-msb');

    simbolos_modulados = miQamModCuad(simbolos, M, phi_err);

    [~, recibidos] = generador_ruido(simbolos_modulados, SNR_dB);

    simbolos_detectados = qamdemod(recibidos, M, 'gray');

    bits_agrupados = de2bi(simbolos_detectados, k, 'left-msb');
    bits_detectados = reshape(bits_agrupados.', [], 1);

    errores = sum(bits ~= bits_detectados);
    BER_orden_cuadratura(i) = errores / length(bits);

end
% GRAFICO

figure(7); %[output:71ef459a]
plot(valores_M, BER_orden_cuadratura, '-o', 'LineWidth', 1.5); %[output:71ef459a]

grid on; %[output:71ef459a]
xlabel('Orden de modulacion (M)'); %[output:71ef459a]
ylabel('BER'); %[output:71ef459a]
title('BER en funcion del orden de modulacion - Error de cuadratura'); %[output:71ef459a]
xticks(valores_M); %[output:71ef459a]
%[text] 3.2.e - CONSTELACIONES CON ERROR DE CUADRATURa
SNR_dB = 25;
phi_err = pi/6;

valores_M = [4 16];

figure(8); %[output:3667e201]

for i = 1:length(valores_M) %[output:group:7da5570f]

    M = valores_M(i);
    [bits, simbolos, ~] = generador_simbolos(N, M);

    % SISTEMA IDEAL
    simbolos_ideales = qammod(simbolos, M, 'gray');
    [~, recibidos_ideales] = generador_ruido(simbolos_ideales, SNR_dB);

    % SISTEMA CON ERROR
    simbolos_error = miQamModCuad(simbolos, M, phi_err);
    [~, recibidos_error] = generador_ruido(simbolos_error, SNR_dB);

    subplot(2,2,2*i-1); %[output:3667e201]
    plot(real(recibidos_ideales), imag(recibidos_ideales), '.');
    grid on;
    axis equal;
    xlabel('Componente I');
    ylabel('Componente Q');
    title(['Ideal - M = ' num2str(M)]);

    subplot(2,2,2*i);
    plot(real(recibidos_error), imag(recibidos_error), '.');
    grid on;
    axis equal;
    xlabel('Componente I');
    ylabel('Componente Q');
    title(['Error de cuadratura - M = ' num2str(M)]);

end %[output:group:7da5570f]

